import axios from "axios";
import "./App.css";
import "./ToDoList.css";
import React, { useState, useEffect, useCallback } from "react";
import { FixedSizeList } from "react-window";
import InfiniteLoader from "react-window-infinite-loader";
import Select from "react-dropdown-select";

function ToDoList() {
  const [tasks, setTasks] = useState([]);
  const [newTask, setNewTask] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [taskTags, setTaskTags] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(0);

  const pageSize = 20005;

  const tagOptions = [
    { label: "Work", value: "work" },
    { label: "Personal", value: "personal" },
    { label: "Urgent", value: "urgent" },
  ];

  useEffect(() => {
    loadMoreTasks(0);
  }, []);

  const loadMoreTasks = useCallback(
    async (currentPage) => {
      if (isLoading || !hasMore) return;

      setIsLoading(true);
      try {
        const response = await axios.get(
          `http://localhost:5001/tasks?start=${
            currentPage * pageSize
          }&limit=${pageSize}`
        );
        if (response.data.length === 0) {
          setHasMore(false);
        } else {
          setTasks((prevTasks) => [...prevTasks, ...response.data]);
          setPage(currentPage + 1);
        }
      } catch (error) {
        console.error("Error loading more tasks:", error);
      }
      setIsLoading(false);
    },
    [isLoading, hasMore, page]
  );

  const filteredTasks = tasks.filter((task) =>
    task.text.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const isItemLoaded = (index) => index < filteredTasks.length;

  const loadMoreItems = async () => {
    if (!isLoading && hasMore) {
      await loadMoreTasks(page);
    }
  };

  const handleInputChange = (e) => setNewTask(e.target.value);
  const handleSearchChange = (e) => setSearchTerm(e.target.value);

  const addTask = async () => {
    if (newTask.trim()) {
      try {
        const response = await axios.post("http://localhost:5001/tasks", {
          text: newTask,
          tags: taskTags.map((tag) => tag.value),
        });
        setTasks((prevTasks) => [response.data, ...prevTasks]);
        setNewTask("");
        setTaskTags([]);
      } catch (error) {
        console.error("Error adding task:", error);
      }
    }
  };

  const deleteTask = async (id) => {
    try {
      await axios.delete(`http://localhost:5001/tasks/${id}`);
      setTasks((prevTasks) => prevTasks.filter((task) => task._id !== id));
    } catch (error) {
      console.error("Error deleting task:", error);
    }
  };

  const moveTaskUp = async (index) => {
    if (index > 0) {
      try {
        const response = await axios.put(
          "http://localhost:5001/tasks/reorder",
          {
            sourceIndex: index,
            destinationIndex: index - 1,
          }
        );
        setTasks(response.data);
      } catch (error) {
        console.error("Error moving task up:", error);
      }
    }
  };

  const moveTaskDown = async (index) => {
    if (index < tasks.length - 1) {
      try {
        const response = await axios.put(
          "http://localhost:5001/tasks/reorder",
          {
            sourceIndex: index,
            destinationIndex: index + 1,
          }
        );
        setTasks(response.data);
      } catch (error) {
        console.error("Error moving task down:", error);
      }
    }
  };

  return (
    <div className="to-do-list">
      <h1>To-Do List</h1>

      <input
        type="text"
        placeholder="Search tasks..."
        value={searchTerm}
        onChange={handleSearchChange}
        className="search-bar"
      />

      {/* Task input & tag selector */}
      <div className="input-section">
        <input
          type="text"
          placeholder="Enter a task..."
          value={newTask}
          onChange={handleInputChange}
          className="task-input"
        />
        <Select
          multi
          options={tagOptions}
          onChange={(values) => setTaskTags(values)}
          values={taskTags}
          placeholder="Select tags"
          style={{ width: "200px" }}
        />
        <button onClick={addTask} className="add-button">
          Add
        </button>
      </div>

      <InfiniteLoader
        isItemLoaded={isItemLoaded}
        itemCount={hasMore ? filteredTasks.length + 1 : filteredTasks.length}
        loadMoreItems={loadMoreItems}
      >
        {({ onItemsRendered, ref }) => (
          <FixedSizeList
            height={600}
            width="100%"
            itemSize={60}
            itemCount={filteredTasks.length}
            onItemsRendered={onItemsRendered}
            ref={ref}
          >
            {({ index, style }) => {
              const task = filteredTasks[index];

              return (
                <div style={style} className="task-item">
                  <span>{task.text}</span>
                  <div className="task-buttons">
                    <button
                      onClick={() => deleteTask(task._id)}
                      className="delete-button"
                    >
                      Delete
                    </button>
                    <button
                      onClick={() => moveTaskUp(index)}
                      className="move-button"
                    >
                      ▲
                    </button>
                    <button
                      onClick={() => moveTaskDown(index)}
                      className="move-button"
                    >
                      ▼
                    </button>
                  </div>
                </div>
              );
            }}
          </FixedSizeList>
        )}
      </InfiniteLoader>

      {isLoading && <p className="loading-text">Loading more tasks...</p>}
    </div>
  );
}

export default ToDoList;
